const S=(o)=>STEPS.push(o);
const inp=(path,val,opt={})=>`<input data-b="${path}" ${opt.t==="n"?'data-t="n" type="number" step="any"':""} value="${esc(val??"")}" placeholder="${esc(opt.ph||"")}" ${opt.st?`style="${opt.st}"`:""}>`;
const ta=(path,val,ph="",rows=4)=>`<textarea data-b="${path}" rows="${rows}" placeholder="${esc(ph)}">${esc(val??"")}</textarea>`;
const sel=(path,val,opts)=>`<select data-b="${path}">${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(val)?"selected":""}>${esc(l)}</option>`;}).join("")}</select>`;
const btn=(act,label,cls="line",extra="")=>`<button class="btn sm ${cls}" data-a="${act}" ${extra}>${label}</button>`;
const lines=t=>String(t||"").split("\n").map(x=>x.trim()).filter(Boolean);
const chk=(ok,msg)=>`<li class="${ok===true?"ok":ok===false?"no":"warn"}">${ok===true?"✔":ok===false?"✖":"!"} ${msg}</li>`;


